create table if not exists public.bank_transaction(bank_tran_id bigint generated always as identity primary key,tran_date date not null,bank_account_id bigint not null references public.bank_account(bank_account_id),transaction_id bigint references public."transaction"(transaction_id) on delete set null,amount numeric(24,6) not null,tran_type text not null,reference_number text);
create table if not exists public.bank_statement(statement_id bigint generated always as identity primary key,statement_date date not null,bank_account_id bigint not null references public.bank_account(bank_account_id),opening_balance numeric(24,6) not null,closing_balance numeric(24,6) not null,unique(statement_date,bank_account_id));
create table if not exists public.bank_reconciliation(reconciliation_id bigint generated always as identity primary key,reconciliation_date date not null,bank_account_id bigint not null references public.bank_account(bank_account_id),fiscal_period_id bigint not null references public.fiscal_periods(fiscal_period_id),status text not null,unique(bank_account_id,fiscal_period_id));
create table if not exists public.bank_transfer(transfer_id bigint generated always as identity primary key,transfer_number text not null unique,from_account_id bigint not null references public.bank_account(bank_account_id),to_account_id bigint not null references public.bank_account(bank_account_id),transaction_id bigint references public."transaction"(transaction_id) on delete set null,amount numeric(24,6) not null check(amount>0),transfer_date date not null,check(from_account_id<>to_account_id));
create table if not exists public.bank_check(check_id bigint generated always as identity primary key,check_number text not null,bank_account_id bigint not null references public.bank_account(bank_account_id),supplier_id bigint references public.suppliers(supplier_id),amount numeric(24,6) not null check(amount>0),status text not null,unique(check_number,bank_account_id));
create table if not exists public.bank_deposit(deposit_id bigint generated always as identity primary key,deposit_number text not null unique,bank_account_id bigint not null references public.bank_account(bank_account_id),customer_payment_id bigint references public.customer_payment(payment_id),deposit_date date not null,total_amount numeric(24,6) not null check(total_amount>0));
do $$declare t text;begin foreach t in array array['bank_transaction','bank_statement','bank_reconciliation','bank_transfer','bank_check','bank_deposit']loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "banking_select" on public.%I',t);execute format('drop policy if exists "banking_insert" on public.%I',t);execute format('drop policy if exists "banking_update" on public.%I',t);execute format('drop policy if exists "banking_delete" on public.%I',t);execute format('create policy "banking_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "banking_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "banking_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "banking_delete" on public.%I for delete to authenticated using(true)',t);end loop;end$$;
